mapper.select:
SELECT community_id AS communityId, community_name AS communityName FROM community
AND community_id = #{communityId}
AND dept_id = #{deptId}
ORDER BY community_sort ASC, create_time DESC

SELECT COUNT(1)
FROM room
WHERE community_id = #{communityId}

SELECT COUNT(1)
FROM community_device
WHERE community_id = #{communityId}

SELECT COUNT(1)
FROM community_fee_bill fb
INNER JOIN room r ON r.room_id = fb.room_id
WHERE r.community_id = #{communityId}
  AND fb.bill_status != '3'
  AND fb.create_time >= #{begin}
  AND fb.create_time < #{end}

SELECT COUNT(1)
FROM community_fee_bill fb
INNER JOIN room r ON r.room_id = fb.room_id
WHERE r.community_id = #{communityId}
  AND fb.bill_status = '2'
  AND fb.create_time >= #{begin}
  AND fb.create_time < #{end}

SELECT COUNT(1)
FROM community_repair_order
WHERE community_id = #{communityId}
  AND create_time >= #{begin}
  AND create_time < #{end}

SELECT COUNT(1)
FROM community_repair_order
WHERE community_id = #{communityId}
  AND status = '1'
  AND create_time >= #{begin}
  AND create_time < #{end}

SELECT COUNT(1)
FROM complaint_suggest
WHERE community_id = #{communityId}
  AND remark IS NULL
  AND create_time >= #{begin}
  AND create_time < #{end}

SELECT COUNT(1)
FROM community_parking_space
WHERE community_id = #{communityId}

SELECT COUNT(1)
FROM community_parking_record pr
WHERE pr.in_time >= #{begin}
  AND pr.in_time < #{end}
  AND (
      EXISTS (
          SELECT 1
          FROM community_vehicle v
          INNER JOIN room r ON r.room_id = v.room_id
          WHERE v.vehicle_id = pr.vehicle_id
            AND r.community_id = #{communityId}
      )
      OR EXISTS (
          SELECT 1
          FROM owner_room od
          INNER JOIN room r ON r.room_id = od.room_id
          WHERE od.owner_id = pr.owner_id
            AND r.community_id = #{communityId}
      )
      OR EXISTS (
          SELECT 1
          FROM community_parking_space ps
          WHERE ps.space_id = pr.space_id
            AND ps.community_id = #{communityId}
      )
  )

SELECT COUNT(*)
FROM community_parking_space


        AND community_id = #{communityId}
